"""Original checks: inputs must be fully accounted for and dependencies ordered."""
import unittest
from src.scheduler import STAGES, run


class OriginalChecks(unittest.TestCase):
    def test_total_work_is_not_lost(self):
        result = run(records=5, deadline=60)
        self.assertEqual(result['busy_units'], 5 * sum(d for _, d in STAGES))
        self.assertEqual(result['delivered'], 5)

    def test_each_completion_follows_its_dependency(self):
        result = run(records=5, deadline=60)
        end = result['finished']
        for r in range(5):
            for i in range(1, len(STAGES)):
                before = end[(r, STAGES[i-1][0])]
                after = end[(r, STAGES[i][0])]
                self.assertLessEqual(before, after)

    def test_no_more_workers_than_capacity(self):
        result = run(records=8, deadline=60, workers=2)
        active = set()
        for e in result['events']:
            key = (e['record'], e['stage'])
            if e['event'] == 'start':
                active.add(key)
                self.assertLessEqual(len(active), 2)
            else:
                active.remove(key)

if __name__ == '__main__':
    unittest.main()

"""Deterministic three-stage scheduler used by the exercise."""
from collections import deque

STAGES = (('fetch', 2), ('decode', 3), ('commit', 1))


def run(records=8, workers=2, deadline=20):
    """Execute records under the original stage-wide barrier scheduler.

    Each record's stage N+1 depends on completion of stage N. A task consumes
    one worker unit per tick and remains on that worker until it finishes.
    """
    remaining = {(r, stage): duration for r in range(records)
                 for stage, duration in STAGES}
    finished, active, events = {}, {}, []
    busy = time = wave = 0
    while (remaining or active) and time < deadline:
        stage = STAGES[wave][0]
        candidates = [(r, stage) for r in range(records)
                      if (r, stage) in remaining and (r, stage) not in active]
        for key in candidates:
            if len(active) >= workers:
                break
            active[key] = remaining.pop(key)
            events.append({'event': 'start', 'record': key[0], 'stage': key[1], 'time': time})
        done = []
        for key in list(active):
            active[key] -= 1
            busy += 1
            if active[key] == 0:
                done.append(key)
        time += 1
        for key in done:
            del active[key]
            finished[key] = time
            events.append({'event': 'finish', 'record': key[0], 'stage': key[1], 'time': time})
        if not active and not any(k[1] == stage for k in remaining):
            wave = min(wave + 1, len(STAGES) - 1)
    delivered = sum(finished.get((r, 'commit'), deadline + 1) <= deadline
                    for r in range(records))
    return {'records': records, 'workers': workers, 'deadline': deadline,
            'busy_units': busy, 'finished': finished, 'events': events,
            'delivered': delivered, 'end_time': time,
            'unstarted_or_incomplete': len(remaining) + len(active)}

"""Deterministic three-stage scheduler used by the exercise."""
STAGES = (('fetch', 2), ('decode', 3), ('commit', 1))


def run(records=8, workers=2, deadline=20):
    """Run ready tasks while respecting per-record dependencies and capacity.

    Ready work is dispatched by record ID, then stage order. A task consumes
    one worker unit per tick and remains on that worker until it finishes.
    """
    remaining = {(r, stage): duration for r in range(records)
                 for stage, duration in STAGES}
    finished, active, events = {}, {}, []
    ready = {(r, STAGES[0][0]) for r in range(records)}
    stage_index = {stage: i for i, (stage, _) in enumerate(STAGES)}
    busy = time = 0
    while (remaining or active) and time < deadline:
        candidates = sorted(ready, key=lambda key: (key[0], stage_index[key[1]]))
        for key in candidates[:max(0, workers - len(active))]:
            ready.remove(key)
            active[key] = remaining.pop(key)
            events.append({'event': 'start', 'record': key[0], 'stage': key[1], 'time': time})
        done = []
        for key in list(active):
            active[key] -= 1
            busy += 1
            if active[key] == 0:
                done.append(key)
        time += 1
        for key in done:
            del active[key]
            finished[key] = time
            events.append({'event': 'finish', 'record': key[0], 'stage': key[1], 'time': time})
            next_index = stage_index[key[1]] + 1
            if next_index < len(STAGES):
                ready.add((key[0], STAGES[next_index][0]))
    delivered = sum(finished.get((r, 'commit'), deadline + 1) <= deadline
                    for r in range(records))
    return {'records': records, 'workers': workers, 'deadline': deadline,
            'busy_units': busy, 'finished': finished, 'events': events,
            'delivered': delivered, 'end_time': time,
            'unstarted_or_incomplete': len(remaining) + len(active)}
